"""Rebuild ../index.html from template.html and the figure generated by figure.py."""
import json, os, subprocess
here = os.path.dirname(os.path.abspath(__file__))
f = json.loads(subprocess.check_output(["python3", os.path.join(here, "figure.py")]))
t = open(os.path.join(here, "template.html"), encoding="utf-8").read()
t = t.replace("__FIGURE__", f["figure"]).replace("__EYE__", json.dumps(f["eye"]))
open(os.path.join(here, "..", "index.html"), "w", encoding="utf-8").write(t)
